package main

import "fmt"

var keypad = map[byte]string{
	'2': "abc", '3': "def", '4': "ghi", '5': "jkl",
	'6': "mno", '7': "pqrs", '8': "tuv", '9': "wxyz",
}

// LetterCombinations returns every string spellable from a phone keypad
// digit sequence — the cartesian product of the digits' letter groups,
// generated by backtracking. Digits outside 2-9 yield no combinations.
func LetterCombinations(digits string) []string {
	if len(digits) == 0 {
		return []string{}
	}
	for i := 0; i < len(digits); i++ {
		if keypad[digits[i]] == "" {
			return []string{}
		}
	}
	out := []string{}
	buf := make([]byte, 0, len(digits))
	var build func(i int)
	build = func(i int) {
		if i == len(digits) {
			out = append(out, string(buf))
			return
		}
		for _, ch := range []byte(keypad[digits[i]]) {
			buf = append(buf, ch)
			build(i + 1)
			buf = buf[:len(buf)-1]
		}
	}
	build(0)
	return out
}

func main() {
	fmt.Println(LetterCombinations("23"))
}
